```cypher
MATCH (so:SalesOrder)-[:IN_TERRITORY]->(t:Territory)
WHERE t.country_code = 'CA' AND date_part('year', so.order_date) = 2023
MATCH (so)-[line:HAS_LINE]->(p:Product)
WITH so, line, p
// Direct demand for PD-R853
OPTIONAL MATCH (p)-[direct:HAS_PART|HAS_SUBASSEMBLY*0..6 (r, n | WHERE (r.valid_from <= so.order_date AND (r.valid_to IS NULL OR so.order_date <= r.valid_to)) AND n.product_number = 'PD-R853')]->(target:Product)
WITH so, line, p, direct
// If direct match exists, it's a path of length 0 (p is PD-R853) or length > 0 (p contains PD-R853)
// We need to sum qty * line.order_qty for all paths where the target is PD-R853
// The variable length pattern above matches paths where the LAST node is PD-R853.
// However, the predicate `n.product_number = 'PD-R853'` applies to the node `n` in the pattern.
// In Kuzu, for variable length paths, `n` refers to the nodes in the path.
// Let's re-evaluate. The pattern `(p)-[e:REL*0..6]->(target)` with predicate on `n` (nodes) is tricky.
// It's safer to match the path and then filter the end node.

// Let's restart the logic for the BOM part.
// We need to find all paths from `p` to any product `comp` where `comp.product_number = 'PD-R853'`.
// The path edges must be valid on `so.order_date`.
// The quantity is the product of `qty` along the path.

MATCH (so:SalesOrder)-[:IN_TERRITORY]->(t:Territory)
WHERE t.country_code = 'CA' AND date_part('year', so.order_date) = 2023
MATCH (so)-[line:HAS_LINE]->(p:Product)
// Find all paths from p to PD-R853 using valid BOM edges
OPTIONAL MATCH path = (p)-[e:HAS_PART|HAS_SUBASSEMBLY*0..6]->(comp:Product)
WHERE comp.product_number = 'PD-R853'
  AND all(r IN rels(path) WHERE r.valid_from <= so.order_date AND (r.valid_to IS NULL OR so.order_date <= r.valid_to))
WITH so, line, p, path
// Calculate the quantity multiplier for this path
// If path length is 0, multiplier is 1. Otherwise, product of qty.
WITH so, line, p, path, 
     CASE WHEN length(path) = 0 THEN 1.0 ELSE list_product([r IN rels(path) | r.qty]) END AS bom_qty
// Total demand for this line item for this specific path to PD-R853
// Note: If p IS PD-R853, there is a path of length 0.
// If p contains PD-R853, there are paths of length > 0.
// We sum line.order_qty * bom_qty for all such paths.
RETURN sum(line.order_qty * bom_qty) AS total_demand
```

```cypher
MATCH (so:SalesOrder)-[:IN_TERRITORY]->(t:Territory {name: 'United Kingdom'})
WHERE date_part('year', so.order_date) = 2024
MATCH (so)-[line:HAS_LINE]->(p:Product)
// Direct sales of HB-T721
OPTIONAL MATCH (p)-[:IN_SUBCATEGORY]->(sc:Subcategory)-[:IN_CATEGORY]->(c:Category {name: 'Bikes'})
WITH so, line, p, c
// For each order line, find all paths from p to HB-T721 via BOM edges valid on order date
// Path length 0 means p IS HB-T721 (direct sale)
// Path length >=1 means HB-T721 is a component in p's BOM
OPTIONAL MATCH path = (p)-[e:HAS_SUBASSEMBLY|HAS_PART*1..6 (r, n | WHERE r.valid_from <= so.order_date AND (r.valid_to IS NULL OR so.order_date <= r.valid_to))]->(target:Product {product_number: 'HB-T721'})
WITH so, line, p, c, path, e
// Calculate quantity multiplier for the path
// If path is null, it's a direct sale (p is HB-T721)
// If path exists, multiply all qty values along the path
WITH so, line, p, c,
     CASE 
         WHEN path IS NULL THEN 0
         ELSE list_product(properties(rels(path), 'qty'))
     END AS bom_qty
// Check if p is HB-T721 for direct sales
WITH so, line, p, c, bom_qty,
     CASE 
         WHEN p.product_number = 'HB-T721' THEN 1
         ELSE 0
     END AS is_direct
// Total demand contribution = (direct units + contained units) * order_qty
// Direct: if p is HB-T721, add order_qty
// Contained: if path exists, add bom_qty * order_qty
WITH so, line, p, c, bom_qty, is_direct,
     (is_direct * line.order_qty) + (CASE WHEN bom_qty > 0 THEN bom_qty * line.order_qty ELSE 0 END) AS demand
RETURN sum(demand) AS total_demand
