```cypher
MATCH (p:Product)-[:IN_SUBCATEGORY]->(:Subcategory)-[:IN_CATEGORY]->(c:Category {name: 'Bikes'})
WHERE EXISTS {
    MATCH (o:SalesOrder)-[:HAS_LINE]->(p), (o)-[:IN_TERRITORY]->(t:Territory {name: 'Southwest'})
    WHERE date_part('year', o.order_date) = 2025
  }
  AND NOT EXISTS {
    MATCH (o2:SalesOrder)-[:HAS_LINE]->(p), (o2)-[:IN_TERRITORY]->(t2:Territory {name: 'Central'})
    WHERE date_part('year', o2.order_date) = 2025
  }
RETURN DISTINCT p.product_number AS product_number
ORDER BY product_number
```

